     "time": "08-27 12:10",
     "ts": 1787803844,
     "summary": "众擎机器人发布具身智能生态合作项目“引擎计划”，面向全球开发者及合作伙伴开放三类技术资产。其中，工具层将开放双通道SDK与仿真本体资产；模型层将逐步开放运控框架及具身模型权重；数据层计划于今年第四季度开放千小时级第一视角（Ego）数据集及十小时级真机数据集。此外，该计划还将开启科研合作、人才培养及二次开发合作三类共创通道。 （文章来源：财联社）",
